/* @lc app=leetcode id=2054 lang=kotlin */ class Solution { fun lb(a: List<Int>, v: Int): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] < v) m + 1 to hi else lo to m } }.last().first fun maxTwoEvents(events: Array<IntArray>): Int = events.sortedBy { it[0] }.let { e -> e.map { it[2] }.reversed().runningFold(0) { m, v -> maxOf(m, v) }.reversed().let { suf -> e.map { it[0] }.let { st -> e.maxOf { it[2] + suf[lb(st, it[1] + 1)] } } } } }